const fs=require("fs");function isTechnicalTerm(s){if(!s||"string"!=typeof s)return!0;const e=s.trim();return e.length<2||(!!e.includes("_")||(!!/^(BIZ|OPT|EVT|INTENT)[-_]/i.test(e)||("catering"===e.toLowerCase()||!(!/^[A-Z0-9_-]{4,}$/.test(e)||["LVI","IT","LKI","Y-TUNNUS"].includes(e)))))}if(fs.existsSync("companies_data.json")){const s=JSON.parse(fs.readFileSync("companies_data.json","utf8"));(Array.isArray(s)?s:s.results||[]).forEach(s=>{if(!s.tags)return;s.tags.split(/[,;]+/).forEach(e=>{isTechnicalTerm(e)&&console.log("[companies_data.json]",s.id,s.nimi,"tag:",e)})})}if(fs.existsSync("search_tags.js")){(fs.readFileSync("search_tags.js","utf8").match(/term:\s*"([^"]+)"/g)||[]).forEach(s=>{const e=s.replace(/term:\s*"([^"]+)"/,"$1");isTechnicalTerm(e)&&console.log("[search_tags.js]",e)})}if(fs.existsSync("needs_config.js")){(fs.readFileSync("needs_config.js","utf8").match(/"tags":\s*\[([^\]]+)\]/g)||[]).forEach(s=>{s.replace(/"tags":\s*\[([^\]]+)\]/,"$1").split(",").map(s=>s.replace(/"/g,"").trim()).forEach(s=>{isTechnicalTerm(s)&&console.log("[needs_config.js tag]",s)})})}